import*as TraceEngine from"../../models/trace/trace.js";import{RecordType,TimelineModelImpl}from"./TimelineModel.js";export class TimelineModelFilter{}export class TimelineVisibleEventsFilter extends TimelineModelFilter{visibleTypes;constructor(e){super(),this.visibleTypes=new Set(e)}accept(e){return this.visibleTypes.has(TimelineVisibleEventsFilter.eventType(e))}static eventType(e){return TraceEngine.Legacy.eventHasCategory(e,TimelineModelImpl.Category.Console)?RecordType.ConsoleTime:TraceEngine.Legacy.eventHasCategory(e,TimelineModelImpl.Category.UserTiming)?RecordType.UserTiming:e.name}}export class TimelineInvisibleEventsFilter extends TimelineModelFilter{invisibleTypes;constructor(e){super(),this.invisibleTypes=new Set(e)}accept(e){return!this.invisibleTypes.has(TimelineVisibleEventsFilter.eventType(e))}}export class ExclusiveNameFilter extends TimelineModelFilter{excludeNames;constructor(e){super(),this.excludeNames=new Set(e)}accept(e){return!this.excludeNames.has(e.name)}}